package com.transiva.app;
import android.app.Activity;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.Gravity;
import android.widget.*;
import android.view.View;
import org.json.JSONObject;
import org.json.JSONArray;
import java.util.Locale;
/** Standalone product detail. Ordering remains in the existing store/TransShop flow. */
public class TransShopProductActivity extends Activity {
 private int blue=Color.rgb(12,108,234); private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} private TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(24,53,87));if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
 @Override public void onCreate(Bundle b){super.onCreate(b);JSONObject shop,item;try{shop=new JSONObject(getIntent().getStringExtra("store_json"));item=new JSONObject(getIntent().getStringExtra("product_json"));}catch(Exception e){finish();return;}getWindow().setStatusBarColor(blue);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(Color.rgb(246,249,255));setContentView(page);ScrollView sc=new ScrollView(this);page.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(16),dp(12),dp(16),dp(16));sc.addView(body);TextView back=text("‹  Detail Produk",22,true);body.addView(back);back.setOnClickListener(v->finish());ImageView image=new ImageView(this);TransShopImages.load(image,TransShopImages.product(item));image.setBackground(bg(Color.WHITE,12));image.setOnClickListener(v->{Intent zoom=new Intent(this,TransShopZoomActivity.class);zoom.putExtra("image_url",TransShopImages.product(item));startActivity(zoom);});LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,dp(260));ip.topMargin=dp(16);body.addView(image,ip);TextView hint=text("⤢ Ketuk foto untuk lihat penuh & zoom",12,false);hint.setGravity(Gravity.CENTER);body.addView(hint);TextView name=text(item.optString("name","Produk"),23,true);name.setPadding(0,dp(14),0,0);body.addView(name);TextView price=text("Rp "+String.format(new Locale("id","ID"),"%,.0f",item.optDouble("price",0)),22,true);price.setTextColor(blue);price.setPadding(0,dp(7),0,dp(10));body.addView(price);TextView store=text("Toko: "+shop.optString("name"),14,true);body.addView(store);TextView desc=text(item.optString("description","Belum ada deskripsi produk."),14,false);desc.setPadding(0,dp(12),0,dp(12));body.addView(desc);LinearLayout selector=new LinearLayout(this);selector.setGravity(Gravity.CENTER_VERTICAL);TextView quantity=text("Jumlah",14,true);selector.addView(quantity,new LinearLayout.LayoutParams(0,-2,1));Button minus=new Button(this);minus.setText("−");TextView number=text(String.valueOf(Math.max(0,getIntent().getIntExtra("selected_quantity",0))),17,true);number.setGravity(Gravity.CENTER);Button plus=new Button(this);plus.setText("+");selector.addView(minus,new LinearLayout.LayoutParams(dp(48),dp(44)));selector.addView(number,new LinearLayout.LayoutParams(dp(42),dp(44)));selector.addView(plus,new LinearLayout.LayoutParams(dp(48),dp(44)));body.addView(selector);minus.setOnClickListener(v->number.setText(String.valueOf(Math.max(0,Integer.parseInt(number.getText().toString())-1))));plus.setOnClickListener(v->number.setText(String.valueOf(Math.min(99,Integer.parseInt(number.getText().toString())+1))));Button choose=new Button(this);choose.setText("Tambah ke pesanan TransShop");choose.setTextColor(Color.WHITE);choose.setAllCaps(false);choose.setBackground(bg(blue,13));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(54));cp.setMargins(dp(16),dp(8),dp(16),dp(16));page.addView(choose,cp);choose.setOnClickListener(v->{int q=Integer.parseInt(number.getText().toString());if(getIntent().hasExtra("product_index")){Intent result=new Intent();result.putExtra("product_index",getIntent().getIntExtra("product_index",-1));result.putExtra("selected_quantity",q);setResult(RESULT_OK,result);finish();}else{Intent intent=new Intent(this,TransShopStoreActivity.class);intent.putExtra("store_json",shop.toString());intent.putExtra("selected_index",findIndex(shop,item));intent.putExtra("selected_quantity",Math.max(1,q));startActivity(intent);finish();}});}
 private int findIndex(JSONObject shop,JSONObject item){JSONArray a=shop.optJSONArray("items");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&x.optString("id").equals(item.optString("id"))&&!x.optString("id").isEmpty())return i;if(x!=null&&x.toString().equals(item.toString()))return i;}return 0;}
}
